/**
 * \author Mr.Nobody
 * \file Crsf_Crc.hpp
 * \ingroup Crsf
 * \brief CRSF CRC-8 calculation functionality module header file.
 *
 * CRSF uses two CRC-8 variants (MSB first, initial value 0, no final XOR):
 * - frame CRC, polynomial 0xD5 (x^7 + x^6 + x^4 + x^2 + x^0), calculated over
 *   frame type and payload (\ref Crsf::Crc8::frameCrc),
 * - command CRC, polynomial 0xBA (x^7 + x^5 + x^4 + x^3 + x^1), calculated over
 *   frame type, destination, origin, command ID and payload of Direct Command
 *   frame (\ref Crsf::Crc8::commandCrc).
 *
 * Lookup table is generated by the compiler.
 */

#ifndef CRSF_CRC_HPP
#define CRSF_CRC_HPP
/* ============================= INCLUDES =================================== */
#include "Crsf_Types.h"                     /* Module C types definition      */
/* ============================= TYPEDEFS =================================== */

/* ========================= SYMBOLIC CONSTANTS ============================= */

/* ========================= EXPORTED MACROS ================================ */

/* ========================= EXPORTED VARIABLES ============================= */

/* ======================== EXPORTED FUNCTIONS ============================== */

namespace Crsf
{
    class Crc8
    {
    public:

        /** Count of items in lookup table */
        static constexpr uint16_t tableSize = 256u;

        /**
         * \brief Creates CRC calculator and its lookup table
         *
         * \param polynomial [in]: CRC polynomial (MSB first, x^8 omitted)
         */
        explicit constexpr Crc8( uint8_t polynomial )
        {
            for( uint16_t tableIndex = 0u; tableSize > tableIndex; tableIndex++ )
            {
                uint8_t crcRegister = static_cast<uint8_t>( tableIndex );

                for( uint8_t bitIndex = 0u; bitsInByte > bitIndex; bitIndex++ )
                {
                    if( 0u != ( crcRegister & msbMask ) )
                    {
                        crcRegister = static_cast<uint8_t>( ( crcRegister << 1u ) ^ polynomial );
                    }
                    else
                    {
                        crcRegister = static_cast<uint8_t>( crcRegister << 1u );
                    }
                }

                table[ tableIndex ] = crcRegister;
            }
        }

        uint8_t Get_Crc   ( const uint8_t * const buff, crsf_MsgLength_t buffLength ) const;
        uint8_t Update_Crc( uint8_t crc, const uint8_t * const buff, crsf_MsgLength_t buffLength ) const;
        uint8_t Get_TableItem( uint8_t index ) const;

        /** Polynomial of frame CRC */
        static constexpr uint8_t framePolynomial = 0xD5u;

        /** Polynomial of Direct Commands CRC */
        static constexpr uint8_t commandPolynomial = 0xBAu;

        /** Frame CRC calculator */
        static const Crc8 frameCrc;

        /** Direct Commands CRC calculator */
        static const Crc8 commandCrc;

    private:

        /** Count of bits in one byte */
        static constexpr uint8_t bitsInByte = 8u;

        /** Mask of the most significant bit */
        static constexpr uint8_t msbMask = 0x80u;

        /** Initial value of CRC register */
        static constexpr uint8_t crcInitialValue = 0x00u;

        /** Lookup table */
        uint8_t table[ tableSize ] = { 0u };
    };
}

#endif /* CRSF_CRC_HPP */
